struct vector3d {
    float x, y, z;
};

inline vector3d operator+(const vector3d& a, const vector3d& b)
{
    vector3d result = {a.x + b.x, a.y + b.y, a.z + b.z};
    return result;
}

inline vector3d operator*(float scale, const vector3d& value)
{
    vector3d result = {scale * value.x, scale * value.y, scale * value.z};
    return result;
}

