    char padding_to_po[0x44];
    po_layout* absolute_po;
public:
    const vector3d& get_abs_position() const { return absolute_po->position; }
};

struct capsule {
    vector3d base;
    vector3d end;
    float radius;
};

class collision_capsule {
    entity* owner;
    char padding[8];
    capsule rel_cap;
    capsule abs_cap;
public:
    void compute_dimensions();
};

void collision_capsule::compute_dimensions()
{
  rel_cap.base = owner->get_abs_position()+(owner->get_radius()*0.125F)*YVEC;
  rel_cap.end = (owner->get_radius()*0.5F)*YVEC+rel_cap.base;
  rel_cap.radius = owner->get_radius()*0.25F;
  abs_cap = rel_cap;
}
